import { apiv2Base, apiv2ServerHeaders } from "@/services/apiv2";

export default function getTourAvailability({ tourSlug, date, pax, activeCurrency, serviceType }: { tourSlug: string; date: string; pax: number; activeCurrency: any; serviceType: any | null; }) {

    var url = `${apiv2Base()}/b2c/availability/${tourSlug}?date=${date}&pax=${pax}&activeCurrency=${activeCurrency}&include_prices=yes&include_rooms=yes&include_customers=yes&preview=false${serviceType ? `&service_type=${serviceType}` : ""}`;

    const res = fetch(url, {
        method: "GET",
        headers: {
            ...apiv2ServerHeaders(),
            "Content-type": "application/json",
        },
        cache: "no-store"
    }).then((res) => res.json())
        // Ağ hatası / kullanıcı sayfadan ayrıldı: reject etmek yerine boş objeye düş.
        // Çağıran .is_regular/.regular_price okuyor (hepsi undefined → falsy) ve loading'i kapatıyor.
        // Aksi halde unhandled rejection → "Failed to fetch" Sentry'e gürültü olur.
        .catch(() => ({}));

    return res;
}