import { parsePlainDate } from "./plainDate";

export default function hasDeposit(getDepartureDate: any) {
    var today = new Date();
    // Kalkış tarihi plain takvim tarihidir; saat dilimi kaymasına karşı yerel gece yarısı olarak kur.
    var departureDate = parsePlainDate(getDepartureDate);

    if (
        Math.round(
            (departureDate.getTime() - today.getTime()) / (1000 * 60 * 60 * 24)
        ) > 30
    )
        return true;
    else return false;
};
